fi
systemctl enable --now ssh
sudo -H -u "$SSH_USER" ssh -i "$MESH" -o IdentitiesOnly=yes -o BatchMode=yes -o StrictHostKeyChecking=accept-new "$SSH_USER@127.0.0.1" true || die 'phase01.error.local_ssh'
DROP=/etc/ssh/sshd_config.d/01-k8s-key-only.conf
cat > "$DROP" <<'EOF'
PubkeyAuthentication yes
PasswordAuthentication no
KbdInteractiveAuthentication no
PermitRootLogin no
EOF
sshd -t
# Drain sshd output before matching: grep -q can otherwise cause SIGPIPE with
# pipefail even when the requested setting is present.
SSHD_EFFECTIVE="$(sshd -T)"
grep -Fxq 'passwordauthentication no' <<< "$SSHD_EFFECTIVE" || die 'phase01.error.password_auth'
grep -Fxq 'kbdinteractiveauthentication no' <<< "$SSHD_EFFECTIVE" || die 'phase01.error.keyboard_auth'
systemctl reload ssh
sudo -H -u "$SSH_USER" ssh -i "$MESH" -o IdentitiesOnly=yes -o BatchMode=yes "$SSH_USER@127.0.0.1" true || die 'phase01.error.ssh_after_password_disable'
# The temporary grant allows a noninteractive, reboot-resumable phase two.
printf '%s ALL=(root) NOPASSWD:ALL\n' "$SSH_USER" > /etc/sudoers.d/90-k8s-bootstrap
chmod 440 /etc/sudoers.d/90-k8s-bootstrap
visudo -cf /etc/sudoers >/dev/null
sudo -u "$SSH_USER" sudo -n true || die 'phase01.error.sudo_setup'
publish_manifest
rm -f "$STATE_DIR/reboot-pending"
touch "$STATE_DIR/ready"
systemctl disable k8s-prepare-resume.service >/dev/null
start_enrollment
atlas_printf phase01.message.phase_complete "$NAME" "$IP"; printf '\n'
